-- Isolated roles, images, drafts and stale-worker checks; all data rolls back.
begin;
do $test$
declare
 owner_id uuid:=gen_random_uuid();admin_id uuid:=gen_random_uuid();staff_id uuid:=gen_random_uuid();org uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();
 batch uuid:=gen_random_uuid();run_id uuid;old_run uuid:=gen_random_uuid();doc uuid:=gen_random_uuid();job uuid:=gen_random_uuid();lease uuid:=gen_random_uuid();req uuid:=gen_random_uuid();
 r jsonb;input jsonb;saved jsonb;key text;original text;denied boolean;count_before bigint;batch2 uuid:=gen_random_uuid();run2 uuid:=gen_random_uuid(); stale jsonb; removed_key text;receipt uuid;lineid uuid;events bigint;oldproduct uuid:=gen_random_uuid();
begin
 assert not has_function_privilege('anon','public.begin_baihuayuan_receipt_manual_review(uuid,uuid)','execute');
 assert not has_table_privilege('authenticated','private.receipt_manual_handoffs','select,insert,update,delete');
 insert into auth.users(id,email,email_confirmed_at,created_at,updated_at) select id,id||'@receipt-review.invalid',now(),now(),now() from unnest(array[owner_id,admin_id,staff_id]) id;
 insert into public.profiles(id,display_name) select id,'隔離核對測試' from unnest(array[owner_id,admin_id,staff_id]) id on conflict(id) do nothing;
 insert into public.organizations(id,name,business_type,store_mode) values(org,'核對隔離測試','SINGLE_RESTAURANT','MULTI');
 insert into public.stores(id,organization_id,name,store_code,created_by) values(a,org,'BeApe','RR'||substr(a::text,1,8),owner_id),(b,org,'Gras','RR'||substr(b::text,1,8),owner_id);
 insert into public.organization_members(organization_id,user_id,role,is_owner,can_manage_business) values(org,owner_id,'OWNER',true,true),(org,admin_id,'LOGISTICS',false,false),(org,staff_id,'STAFF',false,false);
 insert into public.staff_identities(organization_id,user_id,display_name,created_by) select org,id,'隔離核對測試',owner_id from unnest(array[owner_id,admin_id,staff_id]) id;
 insert into public.store_memberships(store_id,organization_id,user_id,login_identifier,role,work_role,assigned_by,can_manage_business) values(a,org,owner_id,'rr-owner','OWNER','OWNER',owner_id,true),(a,org,admin_id,'rr-admin','LOGISTICS','LOGISTICS',owner_id,false),(a,org,staff_id,'rr-staff','STAFF','STAFF',owner_id,false),(b,org,owner_id,'rr-owner-b','OWNER','OWNER',owner_id,true);
 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated')::text,true);

 insert into public.receipt_upload_batches(id,organization_id,store_id,store_name,work_date,uploaded_by,batch_number,status,group_mode) values(batch,org,a,'BeApe',current_date,owner_id,'HANDOFF-QA','PROCESSING','SAME_RECEIPT');
 original:=org||'/'||batch||'/fixture.jpg';
 insert into public.receipt_documents(id,organization_id,batch_id,original_filename,storage_path,mime_type,byte_size,content_sha256,page_order) values(doc,org,batch,'fixture.jpg',original,'image/jpeg',4,repeat('a',64),1);
 insert into storage.objects(bucket_id,name,metadata) values('receipt-documents',original,'{"size":4}');
 insert into public.receipt_ocr_runs(id,organization_id,batch_id,version,provider,model,prompt_version,status,started_by) values(old_run,org,batch,1,'FIXTURE','fixture','fixture','PROCESSING',owner_id);
 insert into public.receipt_ocr_jobs(id,organization_id,batch_id,requested_by,status,lease_token,locked_at) values(job,org,batch,owner_id,'RUNNING',lease,now());
 -- Cross-store and staff writes must be denied before takeover.
 denied:=false;begin perform public.begin_baihuayuan_receipt_manual_review(b,batch);exception when insufficient_privilege then denied:=true;end;assert denied;
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 denied:=false;begin perform public.begin_baihuayuan_receipt_manual_review(a,batch);exception when insufficient_privilege then denied:=true;end;assert denied;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 set local role authenticated;
 run_id:=public.begin_baihuayuan_receipt_manual_review(a,batch);
 assert public.begin_baihuayuan_receipt_manual_review(a,batch)=run_id,'takeover not idempotent';
 key:=public.add_baihuayuan_receipt_draft_row(a,batch,run_id,req);
 assert public.add_baihuayuan_receipt_draft_row(a,batch,run_id,req)=key,'row retry duplicated';
 reset role;
 assert (select count(*) from public.receipt_ocr_fields where ocr_run_id=run_id and row_key=key)=6;
 assert (select status='FAILED' and lease_token is null and last_error='MANUAL_REVIEW' from public.receipt_ocr_jobs where id=job);
 denied:=false;begin perform public.commit_pilot_receipt_ocr(job,lease,old_run,'[]','{}');exception when raise_exception then denied:=sqlerrm='OCR_JOB_LEASE_LOST';end;assert denied,'late OCR committed';
 denied:=false;begin perform public.create_receipt_ocr_run(org,batch,'x','x','x',owner_id);exception when raise_exception then denied:=sqlerrm='RECEIPT_MANUAL_REVIEW_ACTIVE';end;assert denied,'new worker replaced manual draft';
 denied:=false;begin perform public.enqueue_receipt_ocr(batch);exception when raise_exception then denied:=sqlerrm='RECEIPT_MANUAL_REVIEW_ACTIVE';end;assert denied,'manual batch requeued';
 r:=public.get_baihuayuan_receipt_accounts(a,null,null,null,batch)->0;
 assert jsonb_array_length(r->'lines')=1,'blank draft row missing';
 input:=jsonb_build_object('source_fingerprint',r->>'source_fingerprint','revision',r->'revision','header',jsonb_build_object('supplier_name','測試廠商','receipt_date',current_date,'document_number',''),'lines',jsonb_build_array(jsonb_build_object('row_key',key,'product_name','牛邊條','specification','','unit','公斤','quantity',null,'unit_price',380,'subtotal',null,'category','食材','note','','handling','NORMAL')),'adjustment',0,'adjustment_note','','tax',null,'total',null,'note','','checked',false);

 insert into public.products(id,organization_id,product_code,name,base_unit) values(oldproduct,org,'QA-OLD','辨識錯誤品名','公斤');
 insert into public.receipt_product_mappings(organization_id,batch_id,row_key,product_id,selected_by) values(org,batch,key,oldproduct,owner_id);
 r:=public.get_baihuayuan_receipt_accounts(a,null,null,null,batch)->0;
 input:=input||jsonb_build_object('source_fingerprint',r->>'source_fingerprint','revision',r->'revision');
 insert into public.suppliers(organization_id,name) values(org,'測試廠商');
 input:=jsonb_set(jsonb_set(jsonb_set(input,'{lines,0,quantity}','36'),'{lines,0,unit_price}','null'),'{lines,0,subtotal}','null');
 assert not has_function_privilege('anon','public.receive_baihuayuan_receipt(uuid,uuid,jsonb,uuid)','execute');
 denied:=false;begin perform public.receive_baihuayuan_receipt(b,batch,input,gen_random_uuid());exception when insufficient_privilege then denied:=true;end;assert denied,'cross-store allowed';
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 denied:=false;begin perform public.receive_baihuayuan_receipt(a,batch,input,gen_random_uuid());exception when insufficient_privilege then denied:=true;end;assert denied,'staff allowed';
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 update public.store_memberships set access_mode='VIEW' where store_id=a and user_id=owner_id;
 denied:=false;begin perform public.receive_baihuayuan_receipt(a,batch,input,gen_random_uuid());exception when insufficient_privilege then denied:=true;end;assert denied,'view allowed';
 update public.store_memberships set access_mode='EDIT' where store_id=a and user_id=owner_id;
 denied:=false;begin perform public.receive_baihuayuan_receipt(a,batch,jsonb_set(input,'{lines,0,quantity}','null'),gen_random_uuid());exception when invalid_parameter_value then denied:=true;end;assert denied,'missing qty received';
 assert not exists(select 1 from public.goods_receipts where source_batch_id=batch);
 req:=gen_random_uuid();set local role authenticated;
 saved:=public.receive_baihuayuan_receipt(a,batch,input,req);
 assert public.receive_baihuayuan_receipt(a,batch,input,req)=saved,'retry duplicated';
 reset role;
 assert saved#>>'{account,received_at}' is not null;
 assert saved#>'{account,lines,0,unit_price}'='null'::jsonb,'unknown price became zero';
 assert saved#>'{account,net}'='null'::jsonb;
 assert (select count(*) from public.goods_receipts where source_batch_id=batch)=1;
 select id into receipt from public.goods_receipts where source_batch_id=batch;
 select id into lineid from public.receipt_lines where receipt_id=receipt;
 assert (select quantity=36 and unit_price_ex_tax is null and product_id<>oldproduct from public.receipt_lines where id=lineid),'corrected item used wrong OCR mapping';
 assert (select count(*) from public.inventory_lot_events where source_id=lineid)=1,'stock event not exactly once';
 events:=(select count(*) from public.inventory_lot_events);
 r:=saved->'account';input:=input||jsonb_build_object('source_fingerprint',r->>'source_fingerprint','revision',r->'revision','lines',r->'lines','entry_completed',true);
 denied:=false;begin perform public.save_baihuayuan_receipt_review(a,batch,jsonb_set(input,'{lines,0,quantity}','40'),gen_random_uuid());exception when invalid_parameter_value then denied:=sqlerrm='RECEIPT_RECEIVED_LOCKED';end;assert denied,'quantity changed after receipt';
 input:=jsonb_set(jsonb_set(input,'{lines,0,unit_price}','50'),'{lines,0,subtotal}','1800');
 set local role authenticated;
 saved:=public.save_baihuayuan_receipt_review(a,batch,input,gen_random_uuid());
 reset role;
 assert saved#>>'{account,lines,0,unit_price}'='50';
 assert saved#>>'{account,net}'='1800';
 assert saved#>'{account,tax}'='null'::jsonb;
 assert (select count(*) from public.inventory_lot_events)=events,'price save reposted stock';
 assert (select quantity=36 from public.receipt_lines where id=lineid);
 assert (select storage_path=original from public.receipt_documents where id=doc);
 assert exists(select 1 from public.receipt_ocr_runs where id=old_run),'original evidence lost';
 r:=saved->'account';input:=input||jsonb_build_object('source_fingerprint',r->>'source_fingerprint','revision',r->'revision','lines',r->'lines');
 perform public.receive_baihuayuan_receipt(a,batch,input,gen_random_uuid());
 assert (select count(*) from public.inventory_lot_events)=events,'second confirmation duplicated';
-- A newly typed line is saved and received atomically, without a separate draft save.
 insert into public.receipt_upload_batches(id,organization_id,store_id,store_name,work_date,uploaded_by,batch_number,status,group_mode) values(batch2,org,a,'BeApe',current_date,owner_id,'RECEIVE-NEW-QA','PROCESSING','SAME_RECEIPT');
 insert into public.receipt_documents(organization_id,batch_id,original_filename,storage_path,mime_type,byte_size,content_sha256,page_order) values(org,batch2,'new.jpg',org||'/'||batch2||'/new.jpg','image/jpeg',4,repeat('b',64),1);
 insert into storage.objects(bucket_id,name,metadata) values('receipt-documents',org||'/'||batch2||'/new.jpg','{"size":4}');
 run2:=public.begin_baihuayuan_receipt_manual_review(a,batch2);
 r:=public.get_baihuayuan_receipt_accounts(a,null,null,null,batch2)->0;
 input:=input||jsonb_build_object('source_fingerprint',r->>'source_fingerprint','revision',r->'revision','removed_row_keys','[]'::jsonb,'lines',jsonb_build_array(jsonb_build_object('row_key','local-new','product_name','牛邊條','specification','','unit','公斤','quantity',2,'unit_price',null,'subtotal',null,'category','食材','note','','handling','NORMAL')));
 input:=jsonb_set(jsonb_set(jsonb_set(input,'{lines,0,quantity}','3.51'),'{lines,0,unit_price}','880'),'{lines,0,subtotal}','3088.8')||'{"tax":154,"total":3243}';
 insert into private.ingredient_price_cache(store_id,product_id,unit,price,source) values(a,oldproduct,'公斤',999,'QA unrelated');
 req:=gen_random_uuid();set local role authenticated;
 saved:=public.receive_baihuayuan_receipt(a,batch2,input,req);
 assert public.receive_baihuayuan_receipt(a,batch2,input,req)=saved;
 reset role;
 assert (select count(*) from public.goods_receipts where source_batch_id=batch2)=1;
 assert (select count(*) from public.receipt_lines where receipt_id in(select id from public.goods_receipts where source_batch_id=batch2))=1;
 assert saved#>>'{account,lines,0,row_key}' like 'entry-%';
 assert (saved#>>'{account,total}')::numeric=3243,'printed total changed';
 assert (saved#>>'{account,net}')::numeric=3088.8,'rounding changed raw subtotal';
 assert (saved#>>'{account,tax}')::numeric=154;
 assert (saved#>>'{account,lines,0,unit_price}')::numeric=880;
 assert exists(select 1 from private.ingredient_price_cache where store_id=a and product_id=oldproduct and price=999),'unrelated cache changed';
 assert exists(select 1 from private.recipe_price_entries where store_id=a and source_ref->>'batch_id'=batch2::text and price=880),'receipt price candidate not synced';
 assert not has_function_privilege('authenticated','private.refresh_ingredient_price_cache(uuid,uuid[])','execute');
 assert saved#>>'{account,received_at}' is not null;
end $test$;
select 'receive nullable prices, authorization, rollback, idempotency, stock and evidence passed' result;
rollback;
